"""One-session self-contained viewer with fixed indices and source evidence."""
import base64,gzip,html,io,json
from pathlib import Path
from PIL import Image


def encoded(image,format='PNG'):
    b=io.BytesIO();image.save(b,format=format,**({'quality':85} if format=='JPEG' else {}));return 'data:image/'+format.lower()+';base64,'+base64.b64encode(b.getvalue()).decode()


def make_report(output,capture,frames,tracking,previews):
    payload=dict(capture=capture,frames=frames,tracking=tracking,assets={})
    for key,(image,mask) in previews.items():
        im=Image.fromarray(image);im.thumbnail((512,512));mm=Image.fromarray((mask*255).astype('uint8')).resize(im.size,Image.Resampling.NEAREST)
        rgba=Image.new('RGBA',im.size,'white');rgba.putalpha(mm)
        payload['assets'][key]=dict(original=encoded(im,'JPEG'),mask=encoded(rgba))
    blob=base64.b64encode(gzip.compress(json.dumps(payload,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode(),mtime=0)).decode()
    template='''<!doctype html><html><head><meta charset="utf-8"><title>New capture inspection</title><style>body{font:17px/1.4 "Times New Roman",serif;background:white;color:#111;max-width:1250px;margin:auto;padding:24px}h1{font-size:28px}button,select,input{font:inherit}button,select{padding:6px}.controls{display:flex;gap:15px;align-items:center;flex-wrap:wrap;margin:18px 0}.panels{display:grid;grid-template-columns:1fr 1fr;gap:20px}.panel{border:1px solid #ccc;padding:12px}canvas{width:100%;background:black;aspect-ratio:4/3}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px "Times New Roman";max-height:350px;overflow:auto}.note{padding:10px;background:#f4f4f4;border-left:3px solid #777}.small{font-size:14px}#frame{flex:1}table{border-collapse:collapse;width:100%;font-size:15px}td,th{border:1px solid #ccc;padding:6px;text-align:left}@media(max-width:750px){.panels{grid-template-columns:1fr}}</style></head><body><h1 id="title">New capture inspection</h1><p id="identity"></p><p class="note">Foreground masks and terminal paths are computational hypotheses. Image indices are not measured servo timing. Point coordinates have no physical scale; local terminal tokens are not anatomical leaf IDs. This pipeline predicts no assay values.</p><p id="loading">Opening embedded capture data…</p><div class="controls"><button id="prev">Previous</button><button id="play">Play indices</button><button id="next">Next</button><label id="label"></label><input id="frame" type="range" min="0" value="0"><select id="mode"><option value="foreground">Foreground</option><option value="original">Original</option><option value="mask">Mask</option><option value="overlay">Mask and terminal evidence</option></select><button id="export">Export current records</button></div><div class="panels"><div class="panel"><h2>RGB</h2><canvas id="rgb" width="1024" height="768"></canvas><p id="rgbstatus" class="small"></p></div><div class="panel"><h2>NoIR</h2><canvas id="noir" width="1024" height="768"></canvas><p id="noirstatus" class="small"></p></div></div><h2>Coverage and measurements</h2><div id="coverage"></div><h2>Conditional terminal points</h2><div id="points"></div><details><summary>Current source, mask and trait records</summary><pre id="records"></pre></details><details><summary>Assays explicitly supplied by the user</summary><pre id="assays"></pre></details><details><summary>Identity, model and numerical provenance</summary><pre id="provenance"></pre></details><script id="payload" type="application/octet-stream">PAYLOAD</script><script>
let data,view=0,timer=null,token=0;const $=id=>document.getElementById(id);function slot(c){return data.frames.find(r=>r.camera===c&&r.view===view)}function image(src){return new Promise(resolve=>{let x=new Image();x.onload=()=>resolve(x);x.src=src})}async function render(){let k=++token;$('frame').value=view;$('label').textContent='Index '+view+' / '+(data.capture.session.steps-1)+' · '+data.capture.session.angles_degrees[view]+'°';let records=[];for(const c of ['rgb','noir']){const r=slot(c),canvas=$(c),ctx=canvas.getContext('2d');ctx.clearRect(0,0,1024,768);ctx.fillStyle='black';ctx.fillRect(0,0,1024,768);records.push(r);$(c+'status').textContent=r.status+(r.structural_usability?' · usable '+r.structural_usability.usable:'');const asset=data.assets[c+':'+view];if(!asset){ctx.fillStyle='white';ctx.font='26px Times New Roman';ctx.fillText('No decoded image at fixed index '+view,60,360);continue;}let [im,mask]=await Promise.all([image(asset.original),image(asset.mask)]);if(k!==token)return;const mode=$('mode').value;const off=document.createElement('canvas');off.width=im.width;off.height=im.height;const a=off.getContext('2d');if(mode==='mask')a.drawImage(mask,0,0);else{a.drawImage(im,0,0);if(mode==='foreground'){a.globalCompositeOperation='destination-in';a.drawImage(mask,0,0);}if(mode==='overlay'){a.globalAlpha=.25;a.drawImage(mask,0,0);}}ctx.drawImage(off,0,0,1024,768);if(mode==='overlay'){for(const n of data.tracking[c]?.tracks||[]){let e=n.angle_evidence?.find(e=>e.view===view);if(!e)continue;ctx.strokeStyle='#48e0dc';ctx.lineWidth=3;ctx.beginPath();ctx.arc(e.predicted_image_fraction[0]*1024,e.predicted_image_fraction[1]*768,8,0,Math.PI*2);ctx.stroke();if(e.observed_path_fraction){ctx.beginPath();e.observed_path_fraction.forEach((p,i)=>i?ctx.lineTo(p[0]*1024,p[1]*768):ctx.moveTo(p[0]*1024,p[1]*768));ctx.stroke();}}}}$('records').textContent=JSON.stringify(records,null,2)}function step(d){view=(view+d+data.capture.session.steps)%data.capture.session.steps;render()}async function start(){let b=$('payload').textContent.trim();$('payload').remove();let bytes=Uint8Array.from(atob(b),c=>c.charCodeAt(0));data=JSON.parse(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text());$('loading').remove();$('title').textContent='Capture '+data.capture.session.sample_id;$('identity').textContent='Plant UID: '+(data.capture.session.plant_uid||'not provided')+' · '+data.capture.session.physical_identity_status;if(data.capture.duplicate_source_hash_warnings?.length)$('identity').textContent+=' · WARNING: '+data.capture.duplicate_source_hash_warnings.length+' identical-byte groups across cameras; inspect source records.';$('frame').max=data.capture.session.steps-1;$('coverage').innerHTML='<table><tr><th>Camera</th><th>Decoded / planned</th><th>Structurally usable</th><th>Summary eligible</th></tr>'+Object.entries(data.capture.camera_summaries).map(([c,s])=>'<tr><td>'+c+'</td><td>'+s.decoded_views+' / '+s.expected_views+'</td><td>'+s.usable_views+'</td><td>'+s.summary_eligible+'</td></tr>').join('')+'</table>';$('points').textContent=Object.entries(data.tracking).map(([c,t])=>c+': '+t.status+' · '+(t.tracks?.length||0)+' terminal hypotheses · '+(t.reason||'')).join(' | ');$('assays').textContent=JSON.stringify(data.capture.assays,null,2);$('provenance').textContent=JSON.stringify({session:data.capture.session,provider:data.capture.provider,provenance:data.capture.provenance,limits:data.capture.limits,duplicate_source_hash_warnings:data.capture.duplicate_source_hash_warnings},null,2);$('prev').onclick=()=>step(-1);$('next').onclick=()=>step(1);$('frame').oninput=()=>{view=Number($('frame').value);render()};$('mode').onchange=render;$('play').onclick=()=>{if(timer){clearInterval(timer);timer=null;$('play').textContent='Play indices'}else{timer=setInterval(()=>step(1),300);$('play').textContent='Pause'}};$('export').onclick=()=>{let value={session:data.capture.session,view,frames:[slot('rgb'),slot('noir')],assays:data.capture.assays};let url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download='capture_view_'+view+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};globalThis.captureWorkbench={counts:()=>({steps:data.capture.session.steps,frames:data.frames.length}),setView:v=>{view=v;render()},records:()=>[slot('rgb'),slot('noir')]};render()}start().catch(e=>$('loading').textContent=e.message)
</script></body></html>'''
    (Path(output)/'report.html').write_text(template.replace('PAYLOAD',blob),encoding='utf-8')
